def decode_frame(frame: bytes):
    if len(frame) != 5 + int.from_bytes(frame[1:3], "little"):
        raise ValueError("short")
    frame_type = frame[0]
    payload_length = int.from_bytes(frame[1:3], "little")
    payload = frame[3:3 + payload_length]
    stored_crc = int.from_bytes(frame[-2:], "little")
    actual_crc = crc16(frame[:3 + payload_length])
    if actual_crc != stored_crc:
        raise ValueError("crc")
    return (frame_type, payload)
